items.notes:
use this data:
  type: "point",
  color: 16777215,            // white
  intensity: 1.5,             // slightly boosted to compensate for shadows
  position: {
    x: 0,
    y: 5,
    z: 0
  },
  distance: 50,
  decay: 2,                   // physically correct falloff

  castShadow: true,

  shadow: {
    mapSize: {
      width: 1024,
      height: 1024
    },
    camera: {
      near: 0.5,
      far: 50                  // should match distance
    },
    bias: -0.0001              // reduces shadow acne
  }
}

Use this to define the light:
  type: "point",
  color: 16777215,            // white
  intensity: 1.5,             // slightly boosted to compensate for shadows
  position: {
    x: 0,
    y: 5,
    z: 0
  },
  distance: 50,
  decay: 2,                   // physically correct falloff

  castShadow: true,

  shadow: {
    mapSize: {
      width: 1024,
      height: 1024
    },
    camera: {
      near: 0.5,
      far: 50                  // should match distance
    },
    bias: -0.0001              // reduces shadow acne
  }
}
